using System.Linq;using UnityEditor;using UnityEngine;public static class BuildHud{public static void Build(){var output=System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../../Payload"));System.IO.Directory.CreateDirectory(output);if(!BuildPipeline.BuildAssetBundles(output,new[]{new AssetBundleBuild{assetBundleName="native-hud.bundle",assetNames=new[]{"Assets/NativeHud.shader"},addressableNames=new[]{"native/hud-sdf"}}},BuildAssetBundleOptions.ForceRebuildAssetBundle,BuildTarget.StandaloneWindows64))throw new System.Exception("HUD shader build failed");if(ShaderUtil.GetShaderMessages(AssetDatabase.LoadAssetAtPath<Shader>("Assets/NativeHud.shader")).Any(m=>m.severity.ToString()=="Error"))throw new System.Exception("HUD shader compile errors");}}